INSERT INTO verses (reference, book, chapter, verse_start, verse_end, text_es, text_en, theme_id) VALUES
('Romanos 10:17', 'Romanos', 10, 17, NULL, 'Así que la fe es por el oír, y el oír, por la palabra de Dios.', 'So then faith comes by hearing, and hearing by the word of God.', 1),
('Gálatas 2:20', 'Gálatas', 2, 20, NULL, 'Con Cristo estoy juntamente crucificado, y ya no vivo yo, mas vive Cristo en mí; y lo que ahora vivo en la carne, lo vivo en la fe del Hijo de Dios.', 'I have been crucified with Christ and I no longer live, but Christ lives in me. The life I now live in the body, I live by faith in the Son of God.', 1),
('Santiago 2:17', 'Santiago', 2, 17, NULL, 'Así también la fe, si no tiene obras, es muerta en sí misma.', 'In the same way, faith by itself, if it is not accompanied by action, is dead.', 1),
('1 Pedro 1:7', '1 Pedro', 1, 7, NULL, 'Para que sometida a prueba vuestra fe, mucho más preciosa que el oro, sea hallada en alabanza, gloria y honra.', 'These have come so that the proven genuineness of your faith—of greater worth than gold—may result in praise, glory and honor.', 1),
('Hebreos 11:6', 'Hebreos', 11, 6, NULL, 'Pero sin fe es imposible agradar a Dios; porque es necesario que el que se acerca a Dios crea que le hay, y que es galardonador de los que le buscan.', 'And without faith it is impossible to please God, because anyone who comes to him must believe that he exists and that he rewards those who earnestly seek him.', 1),
('Efesios 2:8-9', 'Efesios', 2, 8, 9, 'Porque por gracia sois salvos por medio de la fe; y esto no de vosotros, pues es don de Dios; no por obras, para que nadie se gloríe.', 'For it is by grace you have been saved, through faith—and this is not from yourselves, it is the gift of God—not by works, so that no one can boast.', 1),
('2 Corintios 5:7', '2 Corintios', 5, 7, NULL, 'Porque por fe andamos, no por vista.', 'For we live by faith, not by sight.', 1),
('Romanos 5:1', 'Romanos', 5, 1, NULL, 'Justificados, pues, por la fe, tenemos paz para con Dios por medio de nuestro Señor Jesucristo.', 'Therefore, since we have been justified through faith, we have peace with God through our Lord Jesus Christ.', 1),
('1 Juan 5:4', '1 Juan', 5, 4, NULL, 'Porque todo lo que es nacido de Dios vence al mundo; y esta es la victoria que ha vencido al mundo, nuestra fe.', 'For everyone born of God overcomes the world. This is the victory that has overcome the world, even our faith.', 1),
('Habacuc 2:4', 'Habacuc', 2, 4, NULL, 'He aquí que aquel cuya alma no es recta, se enorgullece; mas el justo por su fe vivirá.', 'See, the enemy is puffed up; his desires are not upright—but the righteous person will live by their faithfulness.', 1),
('Marcos 9:23', 'Marcos', 9, 23, NULL, 'Jesús le dijo: Si puedes creer, al que cree todo le es posible.', 'Jesus said to him, "If you can believe, all things are possible to him who believes."', 1),
('Lucas 17:6', 'Lucas', 17, 6, NULL, 'Entonces el Señor dijo: Si tuvierais fe como un grano de mostaza, podríais decir a este sicómoro: Desarráigate, y plántate en el mar; y os obedecería.', 'He replied, "If you have faith as small as a mustard seed, you can say to this mulberry tree, Be uprooted and planted in the sea, and it will obey you."', 1),
('Salmos 37:5', 'Salmos', 37, 5, NULL, 'Encomienda a Jehová tu camino, y confía en él; y él hará.', 'Commit your way to the Lord; trust in him and he will do this.', 1),
('Isaías 41:10', 'Isaías', 41, 10, NULL, 'No temas, porque yo estoy contigo; no desmayes, porque yo soy tu Dios que te esfuerzo; siempre te ayudaré, siempre te sustentaré con la diestra de mi justicia.', 'So do not fear, for I am with you; do not be dismayed, for I am your God. I will strengthen you and help you; I will uphold you with my righteous right hand.', 1);
INSERT INTO verses (reference, book, chapter, verse_start, verse_end, text_es, text_en, theme_id) VALUES
('Juan 3:16', 'Juan', 3, 16, NULL, 'Porque de tal manera amó Dios al mundo, que ha dado a su Hijo unigénito, para que todo aquel que en él cree, no se pierda, mas tenga vida eterna.', 'For God so loved the world that he gave his one and only Son, that whoever believes in him shall not perish but have eternal life.', 2),
('1 Juan 4:19', '1 Juan', 4, 19, NULL, 'Nosotros le amamos a él, porque él nos amó primero.', 'We love because he first loved us.', 2),
('Romanos 5:8', 'Romanos', 5, 8, NULL, 'Mas Dios muestra su amor para con nosotros, en que siendo aún pecadores, Cristo murió por nosotros.', 'But God demonstrates his own love for us in this: While we were still sinners, Christ died for us.', 2),
('1 Corintios 13:13', '1 Corintios', 13, 13, NULL, 'Y ahora permanecen la fe, la esperanza y el amor, estos tres; pero el mayor de ellos es el amor.', 'And now these three remain: faith, hope and love. But the greatest of these is love.', 2),
('Efesios 3:17-19', 'Efesios', 3, 17, 19, 'Para que habite Cristo por la fe en vuestros corazones, a fin de que, arraigados y cimentados en amor, seáis plenamente capaces de comprender con todos los santos cuál sea la anchura, la longitud, la profundidad y la altura, y de conocer el amor de Cristo.', 'So that Christ may dwell in your hearts through faith. And I pray that you may have power to grasp how wide and long and high and deep is the love of Christ.', 2),
('1 Juan 4:16', '1 Juan', 4, 16, NULL, 'Y nosotros hemos conocido y creído el amor que Dios tiene para con nosotros. Dios es amor; y el que permanece en amor, permanece en Dios, y Dios en él.', 'And so we know and rely on the love God has for us. God is love. Whoever lives in love lives in God, and God in them.', 2),
('Cantar de los Cantares 8:7', 'Cantar de los Cantares', 8, 7, NULL, 'Las muchas aguas no podrán apagar el amor, ni lo ahogarán los ríos. Si diese el hombre todos los bienes de su casa por este amor, de cierto lo menospreciarían.', 'Many waters cannot quench love; rivers cannot sweep it away. If one were to give all the wealth of one''s house for love, it would be utterly scorned.', 2),
('Gálatas 5:22', 'Gálatas', 5, 22, NULL, 'Mas el fruto del Espíritu es amor, gozo, paz, paciencia, benignidad, bondad, fe.', 'But the fruit of the Spirit is love, joy, peace, forbearance, kindness, goodness, faithfulness.', 2),
('1 Pedro 4:8', '1 Pedro', 4, 8, NULL, 'Y ante todo, tened entre vosotros ferviente amor; porque el amor cubrirá multitud de pecados.', 'Above all, love each other deeply, because love covers over a multitude of sins.', 2),
('Proverbios 10:12', 'Proverbios', 10, 12, NULL, 'El odio despierta rencillas; pero el amor cubrirá todas las faltas.', 'Hatred stirs up conflict, but love covers over all wrongs.', 2),
('Mateo 22:37-39', 'Mateo', 22, 37, 39, 'Jesús le dijo: Amarás al Señor tu Dios con todo tu corazón, y con toda tu alma, y con toda tu mente. Este es el primero y grande mandamiento. Y el segundo es semejante: Amarás a tu prójimo como a ti mismo.', 'Jesus replied: Love the Lord your God with all your heart and with all your soul and with all your mind. This is the first and greatest commandment. And the second is like it: Love your neighbor as yourself.', 2),
('Sofonías 3:17', 'Sofonías', 3, 17, NULL, 'Jehová está en medio de ti, poderoso, él salvará; se gozará sobre ti con alegría, callará de amor, se regocijará sobre ti con cánticos.', 'The Lord your God is with you, the Mighty Warrior who saves. He will take great delight in you; in his love he will no longer rebuke you, but will rejoice over you with singing.', 2),
('Deuteronomio 7:9', 'Deuteronomio', 7, 9, NULL, 'Conoce, pues, que Jehová tu Dios es Dios, Dios fiel, que guarda el pacto y la misericordia a los que le aman y guardan sus mandamientos, hasta mil generaciones.', 'Know therefore that the Lord your God is God; he is the faithful God, keeping his covenant of love to a thousand generations of those who love him and keep his commandments.', 2);
INSERT INTO verses (reference, book, chapter, verse_start, verse_end, text_es, text_en, theme_id) VALUES
('Salmos 31:24', 'Salmos', 31, 24, NULL, 'Esforzaos todos vosotros los que esperáis en Jehová, y tome aliento vuestro corazón.', 'Be strong and take heart, all you who hope in the Lord.', 3),
('Salmos 130:5', 'Salmos', 130, 5, NULL, 'Esperé yo a Jehová, esperó mi alma; en su palabra he esperado.', 'I wait for the Lord, my whole being waits, and in his word I put my hope.', 3),
('Romanos 5:5', 'Romanos', 5, 5, NULL, 'Y la esperanza no avergüenza; porque el amor de Dios ha sido derramado en nuestros corazones por el Espíritu Santo que nos fue dado.', 'And hope does not put us to shame, because God''s love has been poured out into our hearts through the Holy Spirit, who has been given to us.', 3),
('Hebreos 6:19', 'Hebreos', 6, 19, NULL, 'La cual tenemos como segura y firme ancla del alma, y que penetra hasta dentro del velo.', 'We have this hope as an anchor for the soul, firm and secure.', 3),
('Isaías 40:31', 'Isaías', 40, 31, NULL, 'Pero los que esperan a Jehová tendrán nuevas fuerzas; levantarán alas como las águilas; correrán, y no se cansarán; caminarán, y no se fatigarán.', 'But those who hope in the Lord will renew their strength. They will soar on wings like eagles; they will run and not grow weary, they will walk and not be faint.', 3),
('1 Pedro 1:3', '1 Pedro', 1, 3, NULL, 'Bendito el Dios y Padre de nuestro Señor Jesucristo, que según su grande misericordia nos hizo renacer para una esperanza viva.', 'Praise be to the God and Father of our Lord Jesus Christ! In his great mercy he has given us new birth into a living hope.', 3),
('Salmos 39:7', 'Salmos', 39, 7, NULL, 'Y ahora, Señor, ¿qué esperaré? Mi esperanza está en ti.', 'But now, Lord, what do I look for? My hope is in you.', 3),
('Miqueas 7:7', 'Miqueas', 7, 7, NULL, 'Mas yo a Jehová miraré, esperaré al Dios de mi salvación; el Dios mío me oirá.', 'But as for me, I watch in hope for the Lord, I wait for God my Savior; my God will hear me.', 3),
('Salmos 71:14', 'Salmos', 71, 14, NULL, 'Mas yo esperaré siempre, y te alabaré más y más.', 'As for me, I will always have hope; I will praise you more and more.', 3),
('Romanos 8:24-25', 'Romanos', 8, 24, 25, 'Porque en esperanza fuimos salvos; pero la esperanza que se ve, no es esperanza; porque lo que alguno ve, ¿a qué esperarlo? Pero si esperamos lo que no vemos, con paciencia lo aguardamos.', 'For in this hope we were saved. But hope that is seen is no hope at all. Who hopes for what they already have? But if we hope for what we do not yet have, we wait for it patiently.', 3),
('Tito 2:13', 'Tito', 2, 13, NULL, 'Aguardando la esperanza bienaventurada y la manifestación gloriosa de nuestro gran Dios y Salvador Jesucristo.', 'While we wait for the blessed hope—the appearing of the glory of our great God and Savior, Jesus Christ.', 3),
('Isaías 61:3', 'Isaías', 61, 3, NULL, 'A ordenar que a los afligidos de Sion se les dé gloria en lugar de ceniza, óleo de gozo en lugar de luto, manto de alegría en lugar del espíritu angustiado.', 'To bestow on them a crown of beauty instead of ashes, the oil of joy instead of mourning, and a garment of praise instead of a spirit of despair.', 3),
('Salmos 62:5', 'Salmos', 62, 5, NULL, 'Alma mía, en Dios solamente reposa, porque de él es mi esperanza.', 'Yes, my soul, find rest in God; my hope comes from him.', 3);
INSERT INTO verses (reference, book, chapter, verse_start, verse_end, text_es, text_en, theme_id) VALUES
('Nehemías 8:10', 'Nehemías', 8, 10, NULL, 'El gozo de Jehová es vuestra fuerza.', 'The joy of the Lord is your strength.', 4),
('Salmos 18:32', 'Salmos', 18, 32, NULL, 'Dios es el que me ciñe de poder, y quien hace perfecto mi camino.', 'It is God who arms me with strength and keeps my way secure.', 4),
('Salmos 27:1', 'Salmos', 27, 1, NULL, 'Jehová es mi luz y mi salvación; ¿de quién temeré? Jehová es la fortaleza de mi vida; ¿de quién he de atemorizarme?', 'The Lord is my light and my salvation—whom shall I fear? The Lord is the stronghold of my life—of whom shall I be afraid?', 4),
('Salmos 46:1', 'Salmos', 46, 1, NULL, 'Dios es nuestro amparo y fortaleza, nuestro pronto auxilio en las tribulaciones.', 'God is our refuge and strength, an ever-present help in trouble.', 4),
('Efesios 6:10', 'Efesios', 6, 10, NULL, 'Por lo demás, hermanos míos, fortaleceos en el Señor, y en el poder de su fuerza.', 'Finally, be strong in the Lord and in his mighty power.', 4),
('Deuteronomio 31:6', 'Deuteronomio', 31, 6, NULL, 'Esforzaos y cobrad ánimo; no temáis, ni tengáis miedo de ellos, porque Jehová tu Dios es el que va contigo; no te dejará, ni te desamparará.', 'Be strong and courageous. Do not be afraid or terrified because of them, for the Lord your God goes with you; he will never leave you nor forsake you.', 4),
('Salmos 28:7', 'Salmos', 28, 7, NULL, 'Jehová es mi fortaleza y mi escudo; en él confió mi corazón, y fui ayudado, por lo que se gozó mi corazón, y con mi cántico le alabaré.', 'The Lord is my strength and my shield; my heart trusts in him, and he helps me.', 4),
('1 Crónicas 16:11', '1 Crónicas', 16, 11, NULL, 'Buscad a Jehová y su poder; buscad siempre su rostro.', 'Look to the Lord and his strength; seek his face always.', 4),
('Salmos 73:26', 'Salmos', 73, 26, NULL, 'Mi carne y mi corazón desfallecen; mas la roca de mi corazón y mi porción es Dios para siempre.', 'My flesh and my heart may fail, but God is the strength of my heart and my portion forever.', 4),
('2 Corintios 12:9', '2 Corintios', 12, 9, NULL, 'Y me ha dicho: Bástate mi gracia; porque mi poder se perfecciona en la debilidad.', 'But he said to me, "My grace is sufficient for you, for my power is made perfect in weakness."', 4),
('Isaías 40:29', 'Isaías', 40, 29, NULL, 'Él da esfuerzo al cansado, y multiplica las fuerzas al que no tiene ningunas.', 'He gives strength to the weary and increases the power of the weak.', 4),
('Salmos 29:11', 'Salmos', 29, 11, NULL, 'Jehová dará poder a su pueblo; Jehová bendecirá a su pueblo con paz.', 'The Lord gives strength to his people; the Lord blesses his people with peace.', 4),
('Salmos 138:3', 'Salmos', 138, 3, NULL, 'El día que clamé, me respondiste; me fortaleciste con vigor en mi alma.', 'When I called, you answered me; you greatly emboldened me.', 4),
('Habacuc 3:19', 'Habacuc', 3, 19, NULL, 'Jehová el Señor es mi fortaleza, el cual hace mis pies como de ciervas, y en mis alturas me hace andar.', 'The Sovereign Lord is my strength; he makes my feet like the feet of a deer, he enables me to tread on the heights.', 4);
INSERT INTO verses (reference, book, chapter, verse_start, verse_end, text_es, text_en, theme_id) VALUES
('Salmos 4:8', 'Salmos', 4, 8, NULL, 'En paz me acostaré, y asimismo dormiré; porque solo tú, Jehová, me haces vivir confiado.', 'In peace I will lie down and sleep, for you alone, Lord, make me dwell in safety.', 5),
('Colosenses 3:15', 'Colosenses', 3, 15, NULL, 'Y la paz de Dios gobierne en vuestros corazones, a la que asimismo fuisteis llamados en un solo cuerpo; y sed agradecidos.', 'Let the peace of Christ rule in your hearts, since as members of one body you were called to peace. And be thankful.', 5),
('Romanos 14:17', 'Romanos', 14, 17, NULL, 'Porque el reino de Dios no es comida ni bebida, sino justicia, paz y gozo en el Espíritu Santo.', 'For the kingdom of God is not a matter of eating and drinking, but of righteousness, peace and joy in the Holy Spirit.', 5),
('Números 6:26', 'Números', 6, 26, NULL, 'Jehová alce sobre ti su rostro, y ponga en ti paz.', 'The Lord turn his face toward you and give you peace.', 5),
('Salmos 119:165', 'Salmos', 119, 165, NULL, 'Mucha paz tienen los que aman tu ley, y no hay para ellos tropiezo.', 'Great peace have those who love your law, and nothing can make them stumble.', 5),
('Mateo 11:28-29', 'Mateo', 11, 28, 29, 'Venid a mí todos los que estáis trabajados y cargados, y yo os haré descansar. Llevad mi yugo sobre vosotros, y aprended de mí, que soy manso y humilde de corazón; y hallaréis descanso para vuestras almas.', 'Come to me, all you who are weary and burdened, and I will give you rest. Take my yoke upon you and learn from me, for I am gentle and humble in heart, and you will find rest for your souls.', 5),
('Salmos 29:11', 'Salmos', 29, 11, NULL, 'Jehová dará poder a su pueblo; Jehová bendecirá a su pueblo con paz.', 'The Lord gives strength to his people; the Lord blesses his people with peace.', 5),
('Romanos 8:6', 'Romanos', 8, 6, NULL, 'Porque el ocuparse de la carne es muerte, pero el ocuparse del Espíritu es vida y paz.', 'The mind governed by the flesh is death, but the mind governed by the Spirit is life and peace.', 5),
('2 Tesalonicenses 3:16', '2 Tesalonicenses', 3, 16, NULL, 'Y el mismo Señor de paz os dé siempre paz en toda manera. El Señor sea con todos vosotros.', 'Now may the Lord of peace himself give you peace at all times and in every way. The Lord be with all of you.', 5),
('Salmos 37:11', 'Salmos', 37, 11, NULL, 'Pero los mansos heredarán la tierra, y se recrearán con abundancia de paz.', 'But the meek will inherit the land and enjoy peace and prosperity.', 5),
('Proverbios 14:30', 'Proverbios', 14, 30, NULL, 'El corazón apacible es vida de la carne; mas la envidia es carcoma de los huesos.', 'A heart at peace gives life to the body, but envy rots the bones.', 5),
('Isaías 32:17', 'Isaías', 32, 17, NULL, 'Y el efecto de la justicia será paz; y la labor de la justicia, reposo y seguridad para siempre.', 'The fruit of that righteousness will be peace; its effect will be quietness and confidence forever.', 5),
('1 Pedro 3:11', '1 Pedro', 3, 11, NULL, 'Apártese del mal, y haga el bien; busque la paz, y sígala.', 'Turn from evil and do good; seek peace and pursue it.', 5);
INSERT INTO verses (reference, book, chapter, verse_start, verse_end, text_es, text_en, theme_id) VALUES
('Proverbios 1:7', 'Proverbios', 1, 7, NULL, 'El principio de la sabiduría es el temor de Jehová; los insensatos desprecian la sabiduría y la enseñanza.', 'The fear of the Lord is the beginning of knowledge, but fools despise wisdom and instruction.', 6),
('Proverbios 9:10', 'Proverbios', 9, 10, NULL, 'El temor de Jehová es el principio de la sabiduría, y el conocimiento del Santísimo es la inteligencia.', 'The fear of the Lord is the beginning of wisdom, and knowledge of the Holy One is understanding.', 6),
('Proverbios 3:13-14', 'Proverbios', 3, 13, 14, 'Bienaventurado el hombre que halla la sabiduría, y que obtiene la inteligencia; porque su ganancia es mejor que la ganancia de la plata.', 'Blessed are those who find wisdom, those who gain understanding, for she is more profitable than silver.', 6),
('Eclesiastés 7:12', 'Eclesiastés', 7, 12, NULL, 'Porque escudo es la ciencia, y escudo es el dinero; mas la sabiduría excede, en que da vida a sus poseedores.', 'Wisdom is a shelter as money is a shelter, but the advantage of knowledge is this: Wisdom preserves those who have it.', 6),
('Proverbios 16:16', 'Proverbios', 16, 16, NULL, 'Mejor es adquirir sabiduría que oro preciado; y adquirir inteligencia vale más que la plata.', 'How much better to get wisdom than gold, to get insight rather than silver!', 6),
('Proverbios 24:14', 'Proverbios', 24, 14, NULL, 'Así será a tu alma el conocimiento de la sabiduría; si la hallares tendrás recompensa, y al fin tu esperanza no será satisfacer.', 'Know also that wisdom is like honey for you: If you find it, there is a future hope for you, and your hope will not be cut off.', 6),
('Santiago 3:17', 'Santiago', 3, 17, NULL, 'Pero la sabiduría que es de lo alto es primeramente pura, después pacífica, amable, benigna, llena de misericordia y de buenos frutos.', 'But the wisdom that comes from heaven is first of all pure; then peace-loving, considerate, submissive, full of mercy and good fruit.', 6),
('Job 12:12', 'Job', 12, 12, NULL, 'En los ancianos está la ciencia, y en la larga edad la inteligencia.', 'Is not wisdom found among the aged? Does not long life bring understanding?', 6),
('Proverbios 19:20', 'Proverbios', 19, 20, NULL, 'Escucha el consejo, y recibe la corrección, para que seas sabio en tu vejez.', 'Listen to advice and accept discipline, and at the end you will be counted among the wise.', 6),
('1 Corintios 1:25', '1 Corintios', 1, 25, NULL, 'Porque lo insensato de Dios es más sabio que los hombres, y lo débil de Dios es más fuerte que los hombres.', 'For the foolishness of God is wiser than human wisdom, and the weakness of God is stronger than human strength.', 6),
('Proverbios 11:2', 'Proverbios', 11, 2, NULL, 'Cuando viene la soberbia, viene también la deshonra; mas con los humildes está la sabiduría.', 'When pride comes, then comes disgrace, but with humility comes wisdom.', 6),
('Daniel 2:21', 'Daniel', 2, 21, NULL, 'Él muda los tiempos y las edades; quita reyes, y pone reyes; da la sabiduría a los sabios, y la ciencia a los entendidos.', 'He changes times and seasons; he deposes kings and raises up others. He gives wisdom to the wise and knowledge to the discerning.', 6),
('Efesios 5:15-16', 'Efesios', 5, 15, 16, 'Mirad, pues, con diligencia cómo andéis, no como necios sino como sabios, aprovechando bien el tiempo, porque los días son malos.', 'Be very careful, then, how you live—not as unwise but as wise, making the most of every opportunity, because the days are evil.', 6);
INSERT INTO verses (reference, book, chapter, verse_start, verse_end, text_es, text_en, theme_id) VALUES
('Isaías 41:10', 'Isaías', 41, 10, NULL, 'No temas, porque yo estoy contigo; no desmayes, porque yo soy tu Dios que te esfuerzo; siempre te ayudaré, siempre te sustentaré con la diestra de mi justicia.', 'So do not fear, for I am with you; do not be dismayed, for I am your God. I will strengthen you and help you.', 7),
('Salmos 23:4', 'Salmos', 23, 4, NULL, 'Aunque ande en valle de sombra de muerte, no temeré mal alguno, porque tú estarás conmigo; tu vara y tu cayado me infundirán aliento.', 'Even though I walk through the darkest valley, I will fear no evil, for you are with me; your rod and your staff, they comfort me.', 7),
('Isaías 49:13', 'Isaías', 49, 13, NULL, 'Cantad alabanzas, oh cielos, y alégrate, tierra; y prorrumpid en alabanzas, oh montes; porque Jehová ha consolado a su pueblo, y de sus pobres tendrá misericordia.', 'Shout for joy, you heavens; rejoice, you earth; burst into song, you mountains! For the Lord comforts his people and will have compassion on his afflicted ones.', 7),
('Juan 16:33', 'Juan', 16, 33, NULL, 'Estas cosas os he hablado para que en mí tengáis paz. En el mundo tendréis aflicción; pero confiad, yo he vencido al mundo.', 'I have told you these things, so that in me you may have peace. In this world you will have trouble. But take heart! I have overcome the world.', 7),
('Apocalipsis 21:4', 'Apocalipsis', 21, 4, NULL, 'Enjugará Dios toda lágrima de los ojos de ellos; y ya no habrá muerte, ni habrá más llanto, ni clamor, ni dolor; porque las primeras cosas pasaron.', 'He will wipe every tear from their eyes. There will be no more death or mourning or crying or pain, for the old order of things has passed away.', 7),
('Salmos 30:5', 'Salmos', 30, 5, NULL, 'Porque un momento será su ira, pero su favor dura toda la vida. Por la noche durará el lloro, y a la mañana vendrá la alegría.', 'For his anger lasts only a moment, but his favor lasts a lifetime; weeping may stay for the night, but rejoicing comes in the morning.', 7),
('Isaías 43:2', 'Isaías', 43, 2, NULL, 'Cuando pases por las aguas, yo estaré contigo; y si por los ríos, no te anegarán. Cuando pases por el fuego, no te quemarás, ni la llama arderá en ti.', 'When you pass through the waters, I will be with you; and when you pass through the rivers, they will not sweep over you.', 7),
('Salmos 46:10', 'Salmos', 46, 10, NULL, 'Estad quietos, y conoced que yo soy Dios; seré exaltado entre las naciones; enaltecido seré en la tierra.', 'Be still, and know that I am God; I will be exalted among the nations, I will be exalted in the earth.', 7),
('Romanos 8:18', 'Romanos', 8, 18, NULL, 'Pues tengo por cierto que las aflicciones del tiempo presente no son comparables con la gloria venidera que en nosotros ha de manifestarse.', 'I consider that our present sufferings are not worth comparing with the glory that will be revealed in us.', 7),
('Salmos 55:22', 'Salmos', 55, 22, NULL, 'Echa sobre Jehová tu carga, y él te sustentará; no dejará para siempre caído al justo.', 'Cast your cares on the Lord and he will sustain you; he will never let the righteous be shaken.', 7),
('Isaías 66:13', 'Isaías', 66, 13, NULL, 'Como aquel a quien consuela su madre, así os consolaré yo a vosotros, y en Jerusalén tomaréis consuelo.', 'As a mother comforts her child, so will I comfort you; and you will be comforted over Jerusalem.', 7),
('Salmos 94:19', 'Salmos', 94, 19, NULL, 'En la multitud de mis pensamientos dentro de mí, tus consolaciones alegraban mi alma.', 'When anxiety was great within me, your consolation brought me joy.', 7),
('Nahúm 1:7', 'Nahúm', 1, 7, NULL, 'Jehová es bueno, fortaleza en el día de la angustia; y conoce a los que en él confían.', 'The Lord is good, a refuge in times of trouble. He cares for those who trust in him.', 7);
INSERT INTO verses (reference, book, chapter, verse_start, verse_end, text_es, text_en, theme_id) VALUES
('Salmos 118:24', 'Salmos', 118, 24, NULL, 'Este es el día que hizo Jehová; nos gozaremos y alegraremos en él.', 'This is the day the Lord has made; let us rejoice and be glad in it.', 8),
('Salmos 103:2', 'Salmos', 103, 2, NULL, 'Bendice, alma mía, a Jehová, y no olvides ninguno de sus beneficios.', 'Praise the Lord, my soul, and forget not all his benefits.', 8),
('Filipenses 4:6', 'Filipenses', 4, 6, NULL, 'Por nada estéis afanosos, sino sean conocidas vuestras peticiones delante de Dios en toda oración y ruego, con acción de gracias.', 'Do not be anxious about anything, but in every situation, by prayer and petition, with thanksgiving, present your requests to God.', 8),
('Efesios 5:20', 'Efesios', 5, 20, NULL, 'Dando siempre gracias por todo al Dios y Padre, en el nombre de nuestro Señor Jesucristo.', 'Always giving thanks to God the Father for everything, in the name of our Lord Jesus Christ.', 8),
('Salmos 95:2', 'Salmos', 95, 2, NULL, 'Lleguemos ante su presencia con alabanza; aclamémosle con cánticos.', 'Let us come before him with thanksgiving and extol him with music and song.', 8),
('Salmos 69:30', 'Salmos', 69, 30, NULL, 'Alabaré yo el nombre de Dios con cántico, lo exaltaré con alabanza.', 'I will praise God''s name in song and glorify him with thanksgiving.', 8),
('1 Crónicas 16:34', '1 Crónicas', 16, 34, NULL, 'Aclamad a Jehová, porque él es bueno; porque su misericordia es eterna.', 'Give thanks to the Lord, for he is good; his love endures forever.', 8),
('Hebreos 12:28', 'Hebreos', 12, 28, NULL, 'Así que, recibiendo nosotros un reino inconmovible, tengamos gratitud, y mediante ella sirvamos a Dios agradándole con temor y reverencia.', 'Therefore, since we are receiving a kingdom that cannot be shaken, let us be thankful, and so worship God acceptably with reverence and awe.', 8),
('Salmos 136:1', 'Salmos', 136, 1, NULL, 'Alabad a Jehová, porque él es bueno, porque para siempre es su misericordia.', 'Give thanks to the Lord, for he is good. His love endures forever.', 8),
('Salmos 9:1', 'Salmos', 9, 1, NULL, 'Te alabaré, oh Jehová, con todo mi corazón; contaré todas tus maravillas.', 'I will give thanks to you, Lord, with all my heart; I will tell of all your wonderful deeds.', 8),
('2 Corintios 9:15', '2 Corintios', 9, 15, NULL, 'Gracias a Dios por su don inefable.', 'Thanks be to God for his indescribable gift!', 8),
('Salmos 106:1', 'Salmos', 106, 1, NULL, 'Aleluya. Alabad a Jehová, porque él es bueno; porque para siempre es su misericordia.', 'Praise the Lord. Give thanks to the Lord, for he is good; his love endures forever.', 8),
('Jonás 2:9', 'Jonás', 2, 9, NULL, 'Mas yo con voz de alabanza te ofreceré sacrificios; pagaré lo que prometí. La salvación es de Jehová.', 'But I, with shouts of grateful praise, will sacrifice to you. What I have vowed I will make good. Salvation comes from the Lord.', 8);
INSERT INTO verses (reference, book, chapter, verse_start, verse_end, text_es, text_en, theme_id) VALUES
('Salmos 25:4-5', 'Salmos', 25, 4, 5, 'Muéstrame, oh Jehová, tus caminos; enséñame tus sendas. Encamíname en tu verdad, y enséñame, porque tú eres el Dios de mi salvación.', 'Show me your ways, Lord, teach me your paths. Guide me in your truth and teach me, for you are God my Savior.', 9),
('Salmos 48:14', 'Salmos', 48, 14, NULL, 'Porque este Dios es Dios nuestro eternamente y para siempre; él nos guiará aun más allá de la muerte.', 'For this God is our God for ever and ever; he will be our guide even to the end.', 9),
('Juan 16:13', 'Juan', 16, 13, NULL, 'Pero cuando venga el Espíritu de verdad, él os guiará a toda la verdad.', 'But when he, the Spirit of truth, comes, he will guide you into all the truth.', 9),
('Salmos 37:23', 'Salmos', 37, 23, NULL, 'Por Jehová son ordenados los pasos del hombre, y él aprueba su camino.', 'The Lord makes firm the steps of the one who delights in him.', 9),
('Isaías 58:11', 'Isaías', 58, 11, NULL, 'Jehová te pastoreará siempre, y en las sequías satisfará tu alma, y dará vigor a tus huesos; y serás como huerto de riego.', 'The Lord will guide you always; he will satisfy your needs in a sun-scorched land and will strengthen your frame.', 9),
('Salmos 23:2-3', 'Salmos', 23, 2, 3, 'En lugares de delicados pastos me hará descansar; junto a aguas de reposo me pastoreará. Confortará mi alma; me guiará por sendas de justicia por amor de su nombre.', 'He makes me lie down in green pastures, he leads me beside quiet waters, he refreshes my soul. He guides me along the right paths for his name''s sake.', 9),
('Éxodo 15:13', 'Éxodo', 15, 13, NULL, 'Condujiste en tu misericordia a este pueblo que redimiste; lo llevaste con tu poder a tu santa morada.', 'In your unfailing love you will lead the people you have redeemed. In your strength you will guide them to your holy dwelling.', 9),
('Salmos 73:24', 'Salmos', 73, 24, NULL, 'Me has guiado según tu consejo, y después me recibirás en gloria.', 'You guide me with your counsel, and afterward you will take me into glory.', 9),
('Salmos 143:10', 'Salmos', 143, 10, NULL, 'Enséñame a hacer tu voluntad, porque tú eres mi Dios; tu buen espíritu me guíe a tierra de rectitud.', 'Teach me to do your will, for you are my God; may your good Spirit lead me on level ground.', 9),
('Isaías 42:16', 'Isaías', 42, 16, NULL, 'Y guiaré a los ciegos por camino que no sabían, les haré andar por sendas que no habían conocido; delante de ellos cambiaré las tinieblas en luz.', 'I will lead the blind by ways they have not known, along unfamiliar paths I will guide them; I will turn the darkness into light before them.', 9),
('Salmos 31:3', 'Salmos', 31, 3, NULL, 'Porque tú eres mi roca y mi castillo; por tu nombre me guiarás y me encaminarás.', 'Since you are my rock and my fortress, for the sake of your name lead and guide me.', 9),
('Proverbios 3:6', 'Proverbios', 3, 6, NULL, 'Reconócelo en todos tus caminos, y él enderezará tus veredas.', 'In all your ways submit to him, and he will make your paths straight.', 9),
('Juan 10:27', 'Juan', 10, 27, NULL, 'Mis ovejas oyen mi voz, y yo las conozco, y me siguen.', 'My sheep listen to my voice; I know them, and they follow me.', 9);
INSERT INTO verses (reference, book, chapter, verse_start, verse_end, text_es, text_en, theme_id) VALUES
('Salmos 138:8', 'Salmos', 138, 8, NULL, 'Jehová cumplirá su propósito en mí; tu misericordia, oh Jehová, es para siempre; no desampares la obra de tus manos.', 'The Lord will vindicate me; your love, Lord, endures forever—do not abandon the works of your hands.', 10),
('Proverbios 19:21', 'Proverbios', 19, 21, NULL, 'Muchos pensamientos hay en el corazón del hombre; mas el consejo de Jehová permanecerá.', 'Many are the plans in a person''s heart, but it is the Lord''s purpose that prevails.', 10),
('Isaías 46:10', 'Isaías', 46, 10, NULL, 'Que anuncio lo por venir desde el principio, y desde la antigüedad lo que aún no era hecho; que digo: Mi consejo permanecerá, y haré todo lo que quiero.', 'I make known the end from the beginning, from ancient times, what is still to come. I say, My purpose will stand, and I will do all that I please.', 10),
('Filipenses 2:13', 'Filipenses', 2, 13, NULL, 'Porque Dios es el que en vosotros produce así el querer como el hacer, por su buena voluntad.', 'For it is God who works in you to will and to act in order to fulfill his good purpose.', 10),
('2 Timoteo 1:9', '2 Timoteo', 1, 9, NULL, 'Quien nos salvó y llamó con llamamiento santo, no conforme a nuestras obras, sino según el propósito suyo y la gracia que nos fue dada en Cristo Jesús.', 'He has saved us and called us to a holy life—not because of anything we have done but because of his own purpose and grace.', 10),
('Colosenses 1:16', 'Colosenses', 1, 16, NULL, 'Porque en él fueron creadas todas las cosas, las que hay en los cielos y las que hay en la tierra, visibles e invisibles; todo fue creado por medio de él y para él.', 'For in him all things were created: things in heaven and on earth, visible and invisible, all things have been created through him and for him.', 10),
('Mateo 5:16', 'Mateo', 5, 16, NULL, 'Así alumbre vuestra luz delante de los hombres, para que vean vuestras buenas obras, y glorifiquen a vuestro Padre que está en los cielos.', 'In the same way, let your light shine before others, that they may see your good deeds and glorify your Father in heaven.', 10),
('Isaías 43:7', 'Isaías', 43, 7, NULL, 'Todos los llamados de mi nombre; para gloria mía los he creado, los formé y los hice.', 'Everyone who is called by my name, whom I created for my glory, whom I formed and made.', 10),
('Salmos 57:2', 'Salmos', 57, 2, NULL, 'Clamaré al Dios Altísimo, al Dios que me favorece.', 'I cry out to God Most High, to God, who vindicates me.', 10),
('Gálatas 1:15', 'Gálatas', 1, 15, NULL, 'Pero cuando agradó a Dios, que me apartó desde el vientre de mi madre, y me llamó por su gracia.', 'But when God, who set me apart from my mother''s womb and called me by his grace, was pleased.', 10),
('Hechos 20:24', 'Hechos', 20, 24, NULL, 'Pero de ninguna cosa hago caso, ni estimo preciosa mi vida para mí mismo, con tal que acabe mi carrera con gozo, y el ministerio que recibí del Señor Jesús.', 'However, I consider my life worth nothing to me; my only aim is to finish the race and complete the task the Lord Jesus has given me.', 10),
('1 Corintios 10:31', '1 Corintios', 10, 31, NULL, 'Si, pues, coméis o bebéis, o hacéis otra cosa, hacedlo todo para la gloria de Dios.', 'So whether you eat or drink or whatever you do, do it all for the glory of God.', 10),
('Marcos 16:15', 'Marcos', 16, 15, NULL, 'Y les dijo: Id por todo el mundo y predicad el evangelio a toda criatura.', 'He said to them, "Go into all the world and preach the gospel to all creation."', 10);
