-- ================================================
-- MANÁ DIGITAL - VERSÍCULOS ADICIONALES
-- Ejecutar después de la instalación inicial
-- Total: ~150 versículos nuevos
-- ================================================

-- ================================================
-- FE (Faith) - theme_id = 1
-- ================================================

-- ================================================
-- AMOR (Love) - theme_id = 2
-- ================================================

-- ================================================
-- ESPERANZA (Hope) - theme_id = 3
-- ================================================

-- ================================================
-- FORTALEZA (Strength) - theme_id = 4
-- ================================================

-- ================================================
-- PAZ (Peace) - theme_id = 5
-- ================================================

-- ================================================
-- SABIDURÍA (Wisdom) - theme_id = 6
-- ================================================

-- ================================================
-- CONSUELO (Comfort) - theme_id = 7
-- ================================================

-- ================================================
-- GRATITUD (Gratitude) - theme_id = 8
-- ================================================

-- ================================================
-- GUÍA (Guidance) - theme_id = 9
-- ================================================

-- ================================================
-- PROPÓSITO (Purpose) - theme_id = 10
-- ================================================

-- ================================================
-- VERIFICACIÓN
-- ================================================
SELECT
    t.name_es AS tema,
    COUNT(v.id) AS total_versiculos
FROM verse_themes t
LEFT JOIN verses v ON t.id = v.theme_id
GROUP BY t.id, t.name_es
ORDER BY t.id;

SELECT CONCAT('Total de versículos: ', COUNT(*)) AS resumen FROM verses;
